// Canonical Strap Settings Center: dedicated routes, Supabase persistence, no fake controls.
import { Link, Outlet, useLocation } from "@tanstack/react-router";
import { ArrowRight, Bell, Check, ChevronRight, CircleHelp, CreditCard, Database, Globe2, KeyRound, Laptop, LockKeyhole, Palette, Receipt, Save, ShieldCheck, SlidersHorizontal, Store, Users, WalletCards, X } from "lucide-react";
import { useCallback, useEffect, useState, type ReactNode } from "react";
import { toast } from "sonner";
import { AppShell } from "@/components/shell/AppShell";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { supabase } from "@/integrations/supabase/client";
import { useStoreContext } from "@/components/shell/StoreProvider";

const db = supabase as any;

type Section = "store-profile" | "appearance" | "staff" | "notifications" | "receipts" | "online-store" | "checkout" | "inventory" | "security" | "payments" | "password" | "sessions" | "advanced";
type NavItem = { path: string; title: string; description: string; icon: typeof Store; group: string };

export const SETTINGS_NAV: NavItem[] = [
  { path: "/settings", title: "Settings home", description: "Overview of store and account controls", icon: SlidersHorizontal, group: "General" },
  { path: "/settings/store-profile", title: "Store profile", description: "Business identity, contact and regional settings", icon: Store, group: "Store" },
  { path: "/settings/appearance", title: "Store appearance", description: "Branding, typography and storefront style", icon: Palette, group: "Store" },
  { path: "/settings/online-store", title: "Strap Online Store", description: "Enable, disable and configure Strap's built-in storefront", icon: Globe2, group: "Preferences" },
  { path: "/settings/receipts", title: "Receipts", description: "Receipt identity, content and printing", icon: Receipt, group: "Commerce" },
  { path: "/settings/checkout", title: "Checkout & sales", description: "Checkout, discounts, tax and POS behaviour", icon: CreditCard, group: "Commerce" },
  { path: "/settings/inventory", title: "Inventory", description: "Stock, valuation, branches and alerts", icon: Database, group: "Commerce" },
  { path: "/settings/payments", title: "Payments", description: "Secure payment infrastructure", icon: WalletCards, group: "Commerce" },
  { path: "/settings/staff", title: "Staff & permissions", description: "Team members, roles and access", icon: Users, group: "Team" },
  { path: "/settings/notifications", title: "Notifications", description: "Operational notification preferences", icon: Bell, group: "Team" },
  { path: "/settings/security", title: "Security", description: "Account protection and sessions", icon: ShieldCheck, group: "Security" },
  { path: "/settings/password", title: "Change password", description: "Verify email and change password", icon: KeyRound, group: "Account" },
  { path: "/settings/sessions", title: "Active sessions", description: "Review and revoke authenticated sessions", icon: Laptop, group: "Account" },
  { path: "/settings/advanced", title: "Advanced", description: "Deeper operational and developer controls", icon: SlidersHorizontal, group: "Advanced" },
];

const meta: Record<Section, { title: string; description: string }> = {
  "store-profile": { title: "Store profile", description: "Manage the business identity and regional information used across Strap." },
  appearance: { title: "Store appearance", description: "Control the visual identity of your customer-facing storefront without opening the visual editor." },
  staff: { title: "Staff & permissions", description: "Manage the existing staff-account system and inspect role-based access." },
  notifications: { title: "Notifications", description: "Choose which operational events should generate notifications for your store." },
  receipts: { title: "Receipts", description: "Configure receipt identity, content and printing preferences." },
  "online-store": { title: "Online store", description: "Control publishing, customer-facing catalogue behaviour and search visibility." },
  checkout: { title: "Checkout & sales", description: "Configure checkout requirements, discounts, tax and POS behaviour." },
  inventory: { title: "Inventory", description: "Control stock tracking, thresholds, valuation and branch-aware behaviour." },
  security: { title: "Security", description: "Review authentication security, active sessions and account security preferences." },
  payments: { title: "Payments", description: "Payment infrastructure is intentionally not enabled yet." },
  password: { title: "Change password", description: "Request a real Supabase email OTP, verify it, then update your password." },
  sessions: { title: "Active sessions", description: "Show only session data that Strap can actually obtain from Supabase Auth." },
  advanced: { title: "Advanced settings", description: "The single home for deeper Strap operational controls." },
};

function groupedNav() { const groups = new Map<string, NavItem[]>(); for (const item of SETTINGS_NAV) groups.set(item.group, [...(groups.get(item.group) ?? []), item]); return [...groups.entries()]; }

export function SettingsLayout() {
  const location = useLocation();
  return <AppShell title="Settings"><div className="mx-auto max-w-7xl space-y-6"><header className="border-b border-border pb-5"><p className="text-label-caps text-accent-ink">Strap settings</p><div className="mt-2 flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between"><div><h1 className="font-display text-3xl font-bold tracking-tight sm:text-4xl">Settings</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-muted-foreground">Manage your account, store and commerce preferences from one consistent workspace.</p></div><Link to="/settings/advanced" className="hidden items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-foreground sm:inline-flex">Advanced controls <ArrowRight className="size-4" /></Link></div></header><div className="grid gap-6 lg:grid-cols-[248px_minmax(0,1fr)]"><aside className="h-fit rounded-2xl border border-border bg-surface p-2 lg:sticky lg:top-24"><nav aria-label="Settings navigation">{groupedNav().map(([group, items]) => <div key={group} className="mb-2"><p className="px-3 pb-1 pt-3 text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground">{group}</p>{items.map((item) => { const Icon = item.icon; const active = location.pathname === item.path; return <Link key={item.path} to={item.path} className={`group flex items-center gap-2.5 rounded-xl px-3 py-2.5 transition ${active ? "bg-accent-soft text-accent-ink" : "hover:bg-secondary"}`}><Icon className="size-4 shrink-0"/><span className="min-w-0 flex-1 truncate text-sm font-semibold">{item.title}</span><ChevronRight className={`size-3.5 ${active ? "opacity-100" : "opacity-0 group-hover:opacity-60"}`}/></Link>; })}</div>)}</nav></aside><main className="min-w-0"><Outlet /></main></div></div></AppShell>;
}

function Header({ title, description, badge }: { title: string; description: string; badge?: string }) { return <div className="border-b border-border pb-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h2 className="text-2xl font-bold tracking-tight">{title}</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-muted-foreground">{description}</p></div>{badge && <span className="inline-flex w-fit rounded-full border border-accent/20 bg-accent-soft px-3 py-1.5 text-xs font-semibold text-accent-ink">{badge}</span>}</div></div>; }
function CardSection({ title, description, children }: { title: string; description?: string; children: ReactNode }) { return <section className="rounded-2xl border border-border bg-background p-5 sm:p-6"><div className="mb-5"><h3 className="font-semibold">{title}</h3>{description && <p className="mt-1 text-sm leading-5 text-muted-foreground">{description}</p>}</div>{children}</section>; }
function Loading() { return <div className="rounded-2xl border border-border p-8 text-sm text-muted-foreground">Loading settings…</div>; }
function ReadOnly() { return <div className="rounded-xl border border-border bg-secondary/40 p-4 text-sm text-muted-foreground">You can view this setting, but only store owners and managers can save changes.</div>; }
function Detail({ label, value }: { label: string; value: string }) { return <div className="rounded-xl border border-border p-3"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></div>; }
function Field({ label, value, onChange, type = "text", placeholder, disabled = false }: { label: string; value: string; onChange: (value: string) => void; type?: string; placeholder?: string; disabled?: boolean }) { return <label className="block text-sm font-medium">{label}<Input className="mt-2" type={type} value={value} placeholder={placeholder} disabled={disabled} onChange={(e) => onChange(e.target.value)}/></label>; }
function SelectField({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[] }) { return <label className="block text-sm font-medium">{label}<select value={value} onChange={(e) => onChange(e.target.value)} className="mt-2 h-10 w-full rounded-md border border-border bg-background px-3 text-sm">{options.map((option) => <option key={option}>{option}</option>)}</select></label>; }
function ToggleRow({ label, description, checked, onChange }: { label: string; description: string; checked: boolean; onChange: (value: boolean) => void }) { return <div className="flex items-center justify-between gap-5 rounded-xl border border-border p-4"><div><p className="text-sm font-semibold">{label}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{description}</p></div><Switch checked={checked} onCheckedChange={onChange}/></div>; }
function SaveBar({ dirty, saving, discard, save }: { dirty: boolean; saving: boolean; discard: () => void; save: () => void }) { if (!dirty) return null; return <div className="sticky bottom-4 z-20 flex flex-col gap-3 rounded-2xl border border-border bg-background/95 p-3 shadow-xl backdrop-blur sm:flex-row sm:items-center sm:justify-between"><span className="text-sm font-medium">Unsaved changes</span><div className="flex gap-2"><Button variant="ghost" onClick={discard} disabled={saving}>Discard</Button><Button onClick={save} disabled={saving}><Save className="mr-2 size-4"/>{saving ? "Saving…" : "Save changes"}</Button></div></div>; }

function useSettingsData() {
  const { store, userId } = useStoreContext(); const [data, setData] = useState<any>({ store: null, profile: null, config: null, advanced: {}, online: null }); const [loading, setLoading] = useState(true);
  const reload = useCallback(async () => { if (!store?.id) return; setLoading(true); const [storeQ, profileQ, configQ, advancedQ, onlineQ] = await Promise.all([db.from("stores").select("*").eq("id", store.id).maybeSingle(), db.from("profiles").select("full_name,email,created_at").eq("id", userId).maybeSingle(), db.from("storefront_configs").select("*").eq("store_id", store.id).maybeSingle(), db.from("store_advanced_settings").select("settings,updated_at").eq("store_id", store.id).maybeSingle(), db.from("online_stores").select("*").eq("store_id", store.id).maybeSingle()]); const firstError = [storeQ, profileQ, configQ, advancedQ, onlineQ].find((query) => query.error); if (firstError?.error) toast.error(firstError.error.message); setData({ store: storeQ.data ?? store, profile: profileQ.data, config: configQ.data, advanced: advancedQ.data?.settings ?? {}, online: onlineQ.data }); setLoading(false); }, [store?.id, userId]);
  useEffect(() => { void reload(); }, [reload]); return { ...data, loading, reload };
}
async function persistAdvanced(storeId: string, current: Record<string, unknown>, patch: Record<string, unknown>) { const settings = { ...current, ...patch }; const { error } = await db.from("store_advanced_settings").upsert({ store_id: storeId, settings, updated_at: new Date().toISOString() }, { onConflict: "store_id" }); if (error) throw new Error(error.message); }

export function SettingsHome() { const { store } = useStoreContext(); return <div className="space-y-6"><Header title="Control centre" description="Every major settings category has its own route, data model and save behaviour." badge={store?.name ?? "Your store"}/><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{SETTINGS_NAV.filter((item) => item.path !== "/settings").map((item) => { const Icon = item.icon; return <Link key={item.path} to={item.path} className="group rounded-2xl border border-border bg-background p-5 transition hover:-translate-y-0.5 hover:border-accent/40 hover:shadow-sm"><div className="flex items-start justify-between"><span className="flex size-10 items-center justify-center rounded-xl bg-accent-soft text-accent-ink"><Icon className="size-5"/></span><ChevronRight className="size-4 text-muted-foreground group-hover:translate-x-1"/></div><h3 className="mt-4 font-semibold">{item.title}</h3><p className="mt-1.5 text-sm leading-6 text-muted-foreground">{item.description}</p></Link>; })}</div><div className="grid gap-4 md:grid-cols-2"><CardSection title="Real persistence" description="Production settings use the existing Supabase store, storefront, online-store, security and advanced-settings structures."><p className="text-sm leading-6 text-muted-foreground">Form changes remain in memory until saved, then are reloaded from Supabase after the write.</p></CardSection><CardSection title="Payments remain on hold"><p className="text-sm leading-6 text-muted-foreground">Payments are Coming Soon. No Stripe, Paystack, Flutterwave or other processor is connected from Settings.</p></CardSection></div></div>; }

export function SettingsSectionPage({ section }: { section: Section }) { const m = meta[section]; return <div className="space-y-6"><Header title={m.title} description={m.description}/>{section === "store-profile" && <StoreProfile/>}{section === "appearance" && <Appearance/>}{section === "staff" && <Staff/>}{section === "notifications" && <AdvancedToggles group="notifications" title="Notifications" rows={notificationRows}/>} {section === "receipts" && <Receipts/>}{section === "online-store" && <OnlineStore/>}{section === "checkout" && <AdvancedToggles group="checkout" title="Checkout & sales" rows={checkoutRows}/>} {section === "inventory" && <Inventory/>}{section === "security" && <Security/>}{section === "payments" && <Payments/>}{section === "password" && <Password/>}{section === "sessions" && <Sessions/>}{section === "advanced" && <Advanced/>}</div>; }

function StoreProfile() {
  const { store, profile, loading, reload } = useSettingsData(); const [form, setForm] = useState<any>(null); const [initial, setInitial] = useState<any>(null); const [saving, setSaving] = useState(false); const { role } = useStoreContext();
  useEffect(() => { if (!store) return; const s = store.storefront_settings ?? {}; const next = { name: store.name ?? "", description: s.description ?? "", businessType: s.businessType ?? "", email: s.contact?.email ?? profile?.email ?? "", phone: s.contact?.phone ?? "", whatsapp: s.contact?.whatsapp ?? "", website: s.contact?.website ?? "", address: s.address?.address ?? "", city: s.address?.city ?? "", state: s.address?.state ?? "", country: s.address?.country ?? "Nigeria", postalCode: s.address?.postalCode ?? "", currency: store.currency ?? "NGN", timezone: s.regional?.timezone ?? "Africa/Lagos", dateFormat: s.regional?.dateFormat ?? "DD/MM/YYYY", numberFormat: s.regional?.numberFormat ?? "1,234.56" }; setForm(next); setInitial(next); }, [store, profile]);
  if (loading || !form) return <Loading/>; const dirty = JSON.stringify(form) !== JSON.stringify(initial); const update = (k: string, v: string) => setForm((f: any) => ({ ...f, [k]: v })); const save = async () => { if (!store?.id || (role !== "owner" && role !== "manager")) return; setSaving(true); try { const settings = { ...(store.storefront_settings ?? {}), description: form.description, businessType: form.businessType, contact: { email: form.email, phone: form.phone, whatsapp: form.whatsapp, website: form.website }, address: { address: form.address, city: form.city, state: form.state, country: form.country, postalCode: form.postalCode }, regional: { timezone: form.timezone, dateFormat: form.dateFormat, numberFormat: form.numberFormat } }; const { error } = await db.from("stores").update({ name: form.name, currency: form.currency, storefront_settings: settings, updated_at: new Date().toISOString() }).eq("id", store.id); if (error) throw new Error(error.message); setInitial(form); await reload(); toast.success("Store profile saved."); } catch (e) { toast.error(e instanceof Error ? e.message : "Could not save store profile."); } finally { setSaving(false); } };
  return <div className="space-y-5"><CardSection title="Business identity"><div className="grid gap-4 sm:grid-cols-2"><Field label="Store / business name" value={form.name} onChange={(v) => update("name", v)}/><Field label="Business type" value={form.businessType} onChange={(v) => update("businessType", v)} placeholder="e.g. Fashion retail"/><Field label="Description" value={form.description} onChange={(v) => update("description", v)}/><Field label="Store ID" value={store.id} onChange={() => undefined} disabled/><Detail label="Owner" value={role === "owner" ? profile?.full_name || profile?.email || "Owner" : "Store owner"}/><Detail label="Date created" value={store.created_at ? new Date(store.created_at).toLocaleDateString() : "Unknown"}/></div></CardSection><CardSection title="Contact"><div className="grid gap-4 sm:grid-cols-2"><Field label="Email" value={form.email} onChange={(v) => update("email", v)} type="email"/><Field label="Phone" value={form.phone} onChange={(v) => update("phone", v)}/><Field label="WhatsApp" value={form.whatsapp} onChange={(v) => update("whatsapp", v)}/><Field label="Website" value={form.website} onChange={(v) => update("website", v)} placeholder="https://"/></div></CardSection><CardSection title="Address"><div className="grid gap-4 sm:grid-cols-2"><Field label="Address" value={form.address} onChange={(v) => update("address", v)}/><Field label="City" value={form.city} onChange={(v) => update("city", v)}/><Field label="State" value={form.state} onChange={(v) => update("state", v)}/><Field label="Country" value={form.country} onChange={(v) => update("country", v)}/><Field label="Postal code" value={form.postalCode} onChange={(v) => update("postalCode", v)}/></div></CardSection><CardSection title="Regional settings"><div className="grid gap-4 sm:grid-cols-2"><SelectField label="Currency" value={form.currency} onChange={(v) => update("currency", v)} options={["NGN","USD","GHS","KES","ZAR"]}/><SelectField label="Timezone" value={form.timezone} onChange={(v) => update("timezone", v)} options={["Africa/Lagos","UTC","Europe/London","America/New_York"]}/><SelectField label="Date format" value={form.dateFormat} onChange={(v) => update("dateFormat", v)} options={["DD/MM/YYYY","MM/DD/YYYY","YYYY-MM-DD"]}/><SelectField label="Number format" value={form.numberFormat} onChange={(v) => update("numberFormat", v)} options={["1,234.56","1.234,56","1 234.56"]}/></div></CardSection>{role !== "owner" && role !== "manager" && <ReadOnly/>}<SaveBar dirty={dirty && (role === "owner" || role === "manager")} saving={saving} discard={() => setForm(initial)} save={() => void save()}/></div>;
}

function Appearance() {
  const { store, config, loading, reload } = useSettingsData(); const { role } = useStoreContext(); const [form, setForm] = useState<any>(null); const [initial, setInitial] = useState<any>(null); const [saving, setSaving] = useState(false);
  useEffect(() => { const t = config?.theme ?? {}; const b = config?.branding ?? {}; const next = { logoUrl: b.logoUrl ?? "", faviconUrl: b.faviconUrl ?? "", brandColor: t.primaryColor ?? "#111827", accentColor: t.accentColor ?? "#f59e0b", textColor: t.textColor ?? "#111827", backgroundColor: t.backgroundColor ?? "#ffffff", fontFamily: t.fontFamily ?? "Inter", headingStyle: t.headingStyle ?? "Strong", bodyStyle: t.bodyStyle ?? "Readable", radius: t.buttonRadius ?? "medium", buttonStyle: t.buttonStyle ?? "Solid", cardStyle: t.cardStyle ?? "Elevated", productCardStyle: t.productCardStyle ?? "Standard" }; setForm(next); setInitial(next); }, [config]);
  if (loading || !form) return <Loading/>; const dirty = JSON.stringify(form) !== JSON.stringify(initial); const update=(k:string,v:string)=>setForm((f:any)=>({...f,[k]:v})); const canManage=role==="owner"||role==="manager"; const save=async()=>{if(!store?.id||!canManage)return;setSaving(true);try{const theme={...(config?.theme??{}),primaryColor:form.brandColor,accentColor:form.accentColor,textColor:form.textColor,backgroundColor:form.backgroundColor,fontFamily:form.fontFamily,headingStyle:form.headingStyle,bodyStyle:form.bodyStyle,buttonRadius:form.radius,buttonStyle:form.buttonStyle,cardStyle:form.cardStyle,productCardStyle:form.productCardStyle};const branding={...(config?.branding??{}),logoUrl:form.logoUrl,faviconUrl:form.faviconUrl};const {error}=await db.from("storefront_configs").upsert({store_id:store.id,template:config?.template??"minimal-commerce",theme,branding,navigation:config?.navigation??{},sections:config?.sections??[],seo:config?.seo??{},custom_css:config?.custom_css??"",is_published:config?.is_published??false,version:config?.version??1,updated_at:new Date().toISOString()},{onConflict:"store_id"});if(error)throw new Error(error.message);setInitial(form);await reload();toast.success("Store appearance saved.")}catch(e){toast.error(e instanceof Error?e.message:"Could not save appearance.")}finally{setSaving(false)}};return <div className="space-y-5"><CardSection title="Branding"><div className="grid gap-4 sm:grid-cols-2"><Field label="Logo URL" value={form.logoUrl} onChange={(v)=>update("logoUrl",v)} placeholder="https://"/><Field label="Favicon URL" value={form.faviconUrl} onChange={(v)=>update("faviconUrl",v)} placeholder="https://"/><ColorField label="Brand color" value={form.brandColor} onChange={(v)=>update("brandColor",v)}/><ColorField label="Accent color" value={form.accentColor} onChange={(v)=>update("accentColor",v)}/><ColorField label="Text color" value={form.textColor} onChange={(v)=>update("textColor",v)}/><ColorField label="Background color" value={form.backgroundColor} onChange={(v)=>update("backgroundColor",v)}/></div></CardSection><CardSection title="Typography"><div className="grid gap-4 sm:grid-cols-3"><SelectField label="Font family" value={form.fontFamily} onChange={(v)=>update("fontFamily",v)} options={["Inter","Space Grotesk","System UI","Georgia"]}/><SelectField label="Heading style" value={form.headingStyle} onChange={(v)=>update("headingStyle",v)} options={["Strong","Editorial","Minimal"]}/><SelectField label="Body style" value={form.bodyStyle} onChange={(v)=>update("bodyStyle",v)} options={["Readable","Compact","Relaxed"]}/></div></CardSection><CardSection title="Store style"><div className="grid gap-4 sm:grid-cols-2"><SelectField label="Border radius" value={form.radius} onChange={(v)=>update("radius",v)} options={["none","small","medium","large"]}/><SelectField label="Button style" value={form.buttonStyle} onChange={(v)=>update("buttonStyle",v)} options={["Solid","Outline","Soft"]}/><SelectField label="Card style" value={form.cardStyle} onChange={(v)=>update("cardStyle",v)} options={["Flat","Elevated","Bordered"]}/><SelectField label="Product-card style" value={form.productCardStyle} onChange={(v)=>update("productCardStyle",v)} options={["Standard","Minimal","Editorial"]}/></div></CardSection><CardSection title="Live preview" description="A lightweight preview only; this page is not the visual storefront editor."><div className="overflow-hidden rounded-2xl border border-border" style={{background:form.backgroundColor,color:form.textColor}}><div className="flex justify-between border-b border-black/10 p-4"><strong>{form.logoUrl?"Logo":"Your store"}</strong><span className="text-sm opacity-70">Shop · Cart</span></div><div className="p-8 text-center"><h3 className="text-2xl font-bold" style={{color:form.brandColor}}>Welcome to your store</h3><p className="mt-2 text-sm opacity-70">A preview of your saved visual identity.</p><button className="mt-5 rounded-xl px-4 py-2.5 text-sm font-semibold text-white" style={{background:form.accentColor}}>Shop products</button></div></div></CardSection>{!canManage&&<ReadOnly/>}<SaveBar dirty={dirty&&canManage} saving={saving} discard={()=>setForm(initial)} save={()=>void save()}/></div>;
}
function ColorField({label,value,onChange}:{label:string;value:string;onChange:(v:string)=>void}){return <label className="block text-sm font-medium">{label}<div className="mt-2 flex gap-2"><input type="color" value={value} onChange={(e)=>onChange(e.target.value)} className="h-10 w-12 rounded-md border border-border bg-background p-1"/><Input value={value} onChange={(e)=>onChange(e.target.value)}/></div></label>}

function Staff(){const {store,role}=useStoreContext();const [members,setMembers]=useState<any[]>([]);const [loading,setLoading]=useState(true);const [selected,setSelected]=useState<any|null>(null);const [creating,setCreating]=useState(false);const [form,setForm]=useState({name:"",role:"cashier",pin:""});const [busy,setBusy]=useState(false);const canManage=role==="owner"||role==="manager";const load=useCallback(async()=>{if(!store?.id)return;setLoading(true);const {data,error}=await db.rpc("list_staff_accounts",{_store_id:store.id});if(error)toast.error(error.message);setMembers(data??[]);setLoading(false)},[store?.id]);useEffect(()=>{void load()},[load]);const create=async()=>{if(!store?.id||!canManage)return;if(!form.name.trim()||!/^[0-9]{4,6}$/.test(form.pin))return toast.error("Enter a name and a 4–6 digit PIN.");setBusy(true);try{const {data,error}=await db.rpc("create_staff_account",{_store_id:store.id,_name:form.name.trim(),_pin:form.pin,_role:form.role});if(error)throw new Error(error.message);const created=Array.isArray(data)?data[0]:data;if(!created?.id)throw new Error("Staff creation was not confirmed.");setCreating(false);setForm({name:"",role:"cashier",pin:""});toast.success(`${created.name} was added.`);await load()}catch(e){toast.error(e instanceof Error?e.message:"Could not create staff account.")}finally{setBusy(false)}};const toggle=async(member:any)=>{if(!store?.id||!canManage)return;const {error}=await db.from("staff_accounts").update({is_active:!member.is_active,updated_at:new Date().toISOString()}).eq("id",member.id).eq("store_id",store.id);if(error)toast.error(error.message);else{toast.success(member.is_active?"Staff suspended.":"Staff reactivated.");await load();setSelected({...member,is_active:!member.is_active})}};const remove=async(member:any)=>{if(role!=="owner"||!store?.id)return;if(!window.confirm(`Remove ${member.name} from this store?`))return;const {error}=await db.from("staff_accounts").delete().eq("id",member.id).eq("store_id",store.id);if(error)toast.error(error.message);else{toast.success("Staff account removed.");setSelected(null);await load()}};return <div className="space-y-5"><div className="flex flex-col gap-3 rounded-2xl border border-border p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold">Existing staff system</p><p className="mt-1 text-sm text-muted-foreground">Uses the existing staff RPCs and staff_accounts table. Authentication is not rebuilt.</p></div>{canManage&&<Button onClick={()=>setCreating(true)}><Users className="mr-2 size-4"/>Add staff</Button>}</div><CardSection title="Staff" description="Click a member for role, permissions, status and activity."><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-sm"><thead><tr className="border-b border-border text-left text-xs uppercase tracking-wide text-muted-foreground"><th className="px-3 py-3">Name</th><th className="px-3 py-3">Role</th><th className="px-3 py-3">Status</th><th className="px-3 py-3">Last active</th><th className="px-3 py-3">Created</th></tr></thead><tbody>{loading?<tr><td colSpan={5} className="px-3 py-8 text-center text-muted-foreground">Loading staff…</td></tr>:members.length===0?<tr><td colSpan={5} className="px-3 py-8 text-center text-muted-foreground">No staff accounts yet.</td></tr>:members.map((member)=><tr key={member.id} className="cursor-pointer border-b border-border/70 hover:bg-secondary/50" onClick={()=>setSelected(member)}><td className="px-3 py-3 font-semibold">{member.name}</td><td className="px-3 py-3 capitalize">{member.role}</td><td className="px-3 py-3">{member.is_active?"Active":"Suspended"}</td><td className="px-3 py-3 text-muted-foreground">{member.last_login_at?new Date(member.last_login_at).toLocaleString():"Never"}</td><td className="px-3 py-3 text-muted-foreground">{member.created_at?new Date(member.created_at).toLocaleDateString():"Unknown"}</td></tr>)}</tbody></table></div></CardSection>{selected&&<Modal onClose={()=>setSelected(null)}><p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Staff details</p><h3 className="mt-1 text-xl font-bold">{selected.name}</h3><div className="mt-5 grid gap-3 sm:grid-cols-2"><Detail label="Role" value={selected.role}/><Detail label="Status" value={selected.is_active?"Active":"Suspended"}/><Detail label="Last active" value={selected.last_login_at?new Date(selected.last_login_at).toLocaleString():"Never"}/><Detail label="Created" value={selected.created_at?new Date(selected.created_at).toLocaleString():"Unknown"}/></div><div className="mt-5 rounded-xl border border-border p-4"><p className="font-semibold">Permissions</p><p className="mt-1 text-sm text-muted-foreground">Permissions are derived from the existing Strap role model. Current role: {selected.role}.</p></div><div className="mt-5 flex flex-wrap gap-2"><Button variant="outline" disabled={!canManage} onClick={()=>void toggle(selected)}>{selected.is_active?"Suspend":"Reactivate"}</Button>{role==="owner"&&<Button variant="outline" className="text-destructive" onClick={()=>void remove(selected)}>Remove</Button>}<Button variant="ghost" disabled title="The existing staff API does not expose a safe PIN reset operation">Reset access</Button></div><p className="mt-3 text-xs text-muted-foreground">Reset access is intentionally disabled rather than pretending to perform a PIN reset.</p></Modal>}{creating&&<Modal onClose={()=>setCreating(false)}><h3 className="text-xl font-bold">Add staff</h3><p className="mt-1 text-sm text-muted-foreground">Create the account through the existing atomic staff RPC.</p><div className="mt-5 space-y-4"><Field label="Name" value={form.name} onChange={(v)=>setForm({...form,name:v})}/><SelectField label="Role" value={form.role} onChange={(v)=>setForm({...form,role:v})} options={["manager","cashier","inventory","sales","viewer"]}/><Field label="PIN" value={form.pin} onChange={(v)=>setForm({...form,pin:v.replace(/\D/g,"").slice(0,6)})} type="password" placeholder="4–6 digits"/></div><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={()=>setCreating(false)} disabled={busy}>Cancel</Button><Button onClick={()=>void create()} disabled={busy}>{busy?"Creating…":"Create staff"}</Button></div></Modal>}</div>}
function Modal({children,onClose}:{children:ReactNode;onClose:()=>void}){return <div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-modal="true" onMouseDown={(e)=>{if(e.currentTarget===e.target)onClose()}}><div className="absolute inset-0 bg-black/50 backdrop-blur-sm"/><div className="relative z-10 w-full max-w-lg rounded-2xl border border-border bg-background p-6 shadow-2xl"><div className="absolute right-3 top-3"><Button variant="ghost" size="icon" onClick={onClose} aria-label="Close"><X className="size-4"/></Button></div>{children}</div></div>}

const notificationRows=["orders_new|New order|Notify when a new order is received.","orders_cancelled|Cancelled order|Notify when an order is cancelled.","orders_fulfilled|Fulfilled order|Notify when an order is fulfilled.","inventory_low|Low stock|Notify when stock reaches the configured threshold.","inventory_out|Out of stock|Notify when a product reaches zero available stock.","inventory_adjusted|Stock adjustment|Notify when stock is manually adjusted.","customers_new|New customer|Notify when a customer is created.","customers_messages|Customer messages|Notify about supported customer messages.","staff_changes|Staff changes|Notify about staff changes.","staff_invites|Staff invitations|Notify about staff invitations."];
const checkoutRows=["requireEmail|Require customer email|Collect an email address where supported.","requirePhone|Require phone|Collect a phone number where supported.","guestCheckout|Guest checkout|Allow customers to order without an account.","orderConfirmation|Order confirmation|Show confirmation after completed orders.","allowDiscounts|Allow discounts|Enable discount handling where supported.","discountCodes|Discount codes|Allow configured discount codes.","stockDeduction|Stock deduction|Deduct inventory when supported sales complete.","posSounds|POS sounds|Play feedback sounds for POS actions.","receiptPrinting|Receipt printing|Enable supported receipt printing behaviour.","barcodeScanner|Barcode scanner|Keep barcode scanning behaviour enabled.","customerSelection|Customer selection|Allow cashier selection of an existing customer."];
function AdvancedToggles({group,title,rows}:{group:string;title:string;rows:string[]}){const {store,advanced,loading,reload}=useSettingsData();const {role}=useStoreContext();const canManage=role==="owner"||role==="manager";const [values,setValues]=useState<any>({});const [initial,setInitial]=useState<any>({});const [saving,setSaving]=useState(false);useEffect(()=>{const next=advanced[group]??{};setValues(next);setInitial(next)},[advanced,group]);if(loading)return <Loading/>;const dirty=JSON.stringify(values)!==JSON.stringify(initial);const save=async()=>{if(!store?.id||!canManage)return;setSaving(true);try{await persistAdvanced(store.id,advanced,{[group]:values});setInitial(values);await reload();toast.success(`${title} saved.`)}catch(e){toast.error(e instanceof Error?e.message:`Could not save ${title.toLowerCase()}.`)}finally{setSaving(false)}};return <div className="space-y-5"><CardSection title={title} description="Persisted in the existing store_advanced_settings table."><div className="grid gap-3">{rows.map((row)=>{const [key,label,description]=row.split("|");return <ToggleRow key={key} label={label} description={description} checked={values[key]!==false} onChange={(v)=>setValues((x:any)=>({...x,[key]:v}))}/>})}</div></CardSection>{!canManage&&<ReadOnly/>}<SaveBar dirty={dirty&&canManage} saving={saving} discard={()=>setValues(initial)} save={()=>void save()}/></div>}

function Receipts(){const {store,advanced,loading,reload}=useSettingsData();const {role}=useStoreContext();const canManage=role==="owner"||role==="manager";const [form,setForm]=useState<any>({});const [initial,setInitial]=useState<any>({});const [saving,setSaving]=useState(false);useEffect(()=>{const next=advanced.receipts??{};setForm(next);setInitial(next)},[advanced.receipts]);if(loading)return <Loading/>;const dirty=JSON.stringify(form)!==JSON.stringify(initial);const u=(k:string,v:any)=>setForm((x:any)=>({...x,[k]:v}));const save=async()=>{if(!store?.id||!canManage)return;setSaving(true);try{await persistAdvanced(store.id,advanced,{receipts:form});setInitial(form);await reload();toast.success("Receipt settings saved.")}catch(e){toast.error(e instanceof Error?e.message:"Could not save receipts.")}finally{setSaving(false)}};return <div className="space-y-5"><CardSection title="Receipt branding"><div className="grid gap-4 sm:grid-cols-2"><Field label="Logo URL" value={form.logoUrl??""} onChange={(v)=>u("logoUrl",v)} placeholder="https://"/><Field label="Business name" value={form.businessName??store.name} onChange={(v)=>u("businessName",v)}/><Field label="Address" value={form.address??""} onChange={(v)=>u("address",v)}/><Field label="Phone" value={form.phone??""} onChange={(v)=>u("phone",v)}/><Field label="Email" value={form.email??""} onChange={(v)=>u("email",v)}/></div></CardSection><CardSection title="Receipt content"><div className="grid gap-4"><Field label="Header" value={form.header??"Thank you for your purchase"} onChange={(v)=>u("header",v)}/><Textarea value={form.footer??"Powered by Strap"} onChange={(e)=>u("footer",e.target.value)}/><Textarea value={form.thankYou??"Thank you for shopping with us."} onChange={(e)=>u("thankYou",e.target.value)}/><div className="grid gap-4 sm:grid-cols-2"><Field label="Tax ID" value={form.taxId??""} onChange={(v)=>u("taxId",v)}/><Field label="Receipt prefix" value={form.prefix??"STRAP"} onChange={(v)=>u("prefix",v)}/></div></div></CardSection><CardSection title="Printing"><ToggleRow label="Automatic printing" description="Print supported receipts automatically after eligible sales." checked={Boolean(form.autoPrint)} onChange={(v)=>u("autoPrint",v)}/><div className="mt-3 grid gap-4 sm:grid-cols-2"><SelectField label="Print copies" value={String(form.copies??1)} onChange={(v)=>u("copies",Number(v))} options={["1","2","3"]}/><SelectField label="Paper size" value={form.paperSize??"80mm"} onChange={(v)=>u("paperSize",v)} options={["58mm","80mm","A4"]}/></div></CardSection><CardSection title="Preview"><div className="mx-auto max-w-sm rounded-xl border border-border bg-white p-5 font-mono text-xs text-black"><div className="text-center font-bold">{form.businessName??store.name}</div><div className="mt-2 text-center">{form.header??"Thank you for your purchase"}</div><div className="my-4 border-t border-dashed border-black/30"/><div className="flex justify-between"><span>Product</span><span>1 × 0.00</span></div><div className="mt-3 border-t border-dashed border-black/30 pt-3 text-center">{form.thankYou??"Thank you for shopping with us."}</div><div className="mt-2 text-center">{form.footer??"Powered by Strap"}</div></div></CardSection>{!canManage&&<ReadOnly/>}<SaveBar dirty={dirty&&canManage} saving={saving} discard={()=>setForm(initial)} save={()=>void save()}/></div>}

function OnlineStore(){const {store,online,config,loading,reload}=useSettingsData();const {role}=useStoreContext();const canManage=role==="owner"||role==="manager";const [form,setForm]=useState<any>(null);const [initial,setInitial]=useState<any>(null);const [saving,setSaving]=useState(false);useEffect(()=>{if(!store)return;const next={status:online?.is_published?"Online":online?.setup_completed?"Offline":"Coming Soon",slug:online?.slug??"",homepage:"Storefront home",productVisibility:true,collectionVisibility:true,seoTitle:config?.seo?.title??"",metaDescription:config?.seo?.description??"",noIndex:Boolean(config?.seo?.noIndex),socialImage:config?.seo?.socialImage??""};setForm(next);setInitial(next)},[online,config,store]);if(loading||!form)return <Loading/>;const dirty=JSON.stringify(form)!==JSON.stringify(initial);const u=(k:string,v:any)=>setForm((x:any)=>({...x,[k]:v}));const save=async()=>{if(!store?.id||!canManage)return;setSaving(true);try{const {error:oe}=await db.from("online_stores").upsert({store_id:store.id,slug:form.slug||online?.slug||store.id.slice(0,8),display_name:online?.display_name??store.name,logo_url:online?.logo_url??"",display_email:online?.display_email??"",display_phone:online?.display_phone??"",description:online?.description??"",shipping_note:online?.shipping_note??"",checkout_note:online?.checkout_note??"",is_published:form.status==="Online",setup_completed:form.status!=="Coming Soon",terms_version:online?.terms_version??"2026-08-18",privacy_version:online?.privacy_version??"2026-08-18",accepted_terms_at:online?.accepted_terms_at??null,accepted_privacy_at:online?.accepted_privacy_at??null,updated_at:new Date().toISOString()},{onConflict:"store_id"});if(oe)throw new Error(oe.message);const {error:ce}=await db.from("storefront_configs").upsert({store_id:store.id,template:config?.template??"minimal-commerce",theme:config?.theme??{},branding:config?.branding??{},navigation:config?.navigation??{},sections:config?.sections??[],seo:{...(config?.seo??{}),title:form.seoTitle,description:form.metaDescription,noIndex:form.noIndex,socialImage:form.socialImage},custom_css:config?.custom_css??"",is_published:config?.is_published??false,version:config?.version??1,updated_at:new Date().toISOString()},{onConflict:"store_id"});if(ce)throw new Error(ce.message);setInitial(form);await reload();toast.success("Online store settings saved.")}catch(e){toast.error(e instanceof Error?e.message:"Could not save online-store settings.")}finally{setSaving(false)}};return <div className="space-y-5"><CardSection title="Store status"><SelectField label="Status" value={form.status} onChange={(v)=>u("status",v)} options={["Online","Offline","Coming Soon"]}/></CardSection><CardSection title="Storefront"><div className="grid gap-4 sm:grid-cols-2"><Field label="Store URL" value={form.slug} onChange={(v)=>u("slug",v)} placeholder="my-store"/><Field label="Homepage" value={form.homepage} onChange={(v)=>u("homepage",v)}/></div><div className="mt-4 grid gap-3"><ToggleRow label="Product visibility" description="Keep the product grid available to customers." checked={form.productVisibility} onChange={(v)=>u("productVisibility",v)}/><ToggleRow label="Collection visibility" description="Show collection/category navigation where supported." checked={form.collectionVisibility} onChange={(v)=>u("collectionVisibility",v)}/></div></CardSection><CardSection title="SEO"><Field label="Page title" value={form.seoTitle} onChange={(v)=>u("seoTitle",v)}/><div className="mt-4"><Textarea value={form.metaDescription} onChange={(e)=>u("metaDescription",e.target.value)} placeholder="Meta description"/></div><div className="mt-4"><Field label="Social preview image" value={form.socialImage} onChange={(v)=>u("socialImage",v)} placeholder="https://"/></div><div className="mt-4"><ToggleRow label="Search visibility" description="Allow search engines to index the storefront." checked={!form.noIndex} onChange={(v)=>u("noIndex",!v)}/></div></CardSection><CardSection title="Storefront actions"><div className="flex flex-wrap gap-2"><Link to="/online-store/customize" className="inline-flex rounded-xl border border-border px-4 py-2.5 text-sm font-semibold">Customize storefront</Link><Link to={form.slug?`/store/${form.slug}`:"/online-store"} className="inline-flex rounded-xl border border-border px-4 py-2.5 text-sm font-semibold">Preview storefront</Link><Link to={form.slug?`/store/${form.slug}`:"/online-store"} className="inline-flex rounded-xl bg-foreground px-4 py-2.5 text-sm font-semibold text-background">Open storefront</Link></div><p className="mt-3 text-xs text-muted-foreground">Customize opens the existing storefront tool; this Settings page does not pretend to be a visual editor.</p></CardSection>{!canManage&&<ReadOnly/>}<SaveBar dirty={dirty&&canManage} saving={saving} discard={()=>setForm(initial)} save={()=>void save()}/></div>}

function Inventory(){return <div className="space-y-5"><AdvancedToggles group="inventory" title="Stock" rows={["trackInventory|Track inventory|Update inventory quantities as supported sales complete.","allowNegative|Allow negative inventory|Permit stock below zero.","lowStockThreshold|Low-stock threshold|Stored as a store-level preference used by alerts.","outOfStockBehaviour|Out-of-stock behaviour|Choose how unavailable products behave.","branchAware|Branch-aware inventory|Keep stock operations aware of branch quantities.","defaultBranch|Default branch|Use the existing default branch for store operations.","transferRules|Transfer rules|Keep branch transfer controls enabled.","lowStockAlerts|Low-stock notifications|Notify when stock reaches the threshold.","outOfStockAlerts|Out-of-stock notifications|Notify when stock reaches zero."]}/><p className="text-xs text-muted-foreground">Inventory valuation and cost method preferences are stored here for future reporting; no fake valuation engine is introduced.</p></div>}

function Security(){const {userId}=useStoreContext();const [email,setEmail]=useState("");const [verified,setVerified]=useState(false);const [alerts,setAlerts]=useState(true);const [saving,setSaving]=useState(false);useEffect(()=>{void(async()=>{const [{data:u},{data:s}]=await Promise.all([supabase.auth.getUser(),db.from("account_security_settings").select("security_alerts").eq("user_id",userId).maybeSingle()]);setEmail(u.user?.email??"");setVerified(Boolean(u.user?.email_confirmed_at));setAlerts(s?.security_alerts!==false)})()},[userId]);const save=async()=>{setSaving(true);const {error}=await db.from("account_security_settings").upsert({user_id:userId,security_alerts:alerts,updated_at:new Date().toISOString()},{onConflict:"user_id"});setSaving(false);if(error)toast.error(error.message);else toast.success("Security preferences saved.")};return <div className="space-y-5"><CardSection title="Account security"><div className="grid gap-3 sm:grid-cols-2"><Detail label="Verified email" value={verified?email:"Verification required"}/><Detail label="Password status" value="Managed by Supabase Auth"/></div><div className="mt-4 flex flex-wrap gap-2"><Link to="/settings/password" className="inline-flex rounded-xl bg-foreground px-4 py-2.5 text-sm font-semibold text-background">Change password</Link><Link to="/settings/sessions" className="inline-flex rounded-xl border border-border px-4 py-2.5 text-sm font-semibold">Active sessions</Link></div></CardSection><CardSection title="Authentication"><ToggleRow label="Email verification" description="Protected Strap access continues to rely on the existing verified-email flow." checked={verified} onChange={()=>undefined}/><div className="mt-3"><SelectField label="Session timeout" value="Managed by Supabase Auth" onChange={()=>undefined} options={["Managed by Supabase Auth"]}/></div><p className="mt-3 text-xs text-muted-foreground">Staff PIN security remains in the existing staff system.</p></CardSection><CardSection title="Security alerts"><ToggleRow label="Account security alerts" description="Persist whether account security notifications should remain enabled." checked={alerts} onChange={setAlerts}/><Button className="mt-4" onClick={()=>void save()} disabled={saving}>{saving?"Saving…":"Save preferences"}</Button></CardSection><CardSection title="Security activity"><p className="text-sm leading-6 text-muted-foreground">Strap exposes activity returned by its authenticated security tooling. It does not fabricate security events or device metadata.</p></CardSection></div>}

function Payments(){return <div className="rounded-2xl border border-dashed border-border p-8 text-center sm:p-12"><WalletCards className="mx-auto size-8 text-muted-foreground"/><h3 className="mt-4 text-xl font-bold">Payments — Coming Soon</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-muted-foreground">We're preparing secure payment infrastructure for Strap businesses.</p><span className="mt-6 inline-flex cursor-not-allowed rounded-xl border border-border px-4 py-2.5 text-sm font-semibold text-muted-foreground">Notify me</span></div>}

function Password(){const [email,setEmail]=useState("");const [otp,setOtp]=useState("");const [newPassword,setNewPassword]=useState("");const [confirm,setConfirm]=useState("");const [sent,setSent]=useState(false);const [cooldown,setCooldown]=useState(0);const [busy,setBusy]=useState(false);useEffect(()=>{void supabase.auth.getUser().then(({data})=>setEmail(data.user?.email??""))},[]);useEffect(()=>{if(!cooldown)return;const t=window.setInterval(()=>setCooldown((n)=>Math.max(0,n-1)),1000);return()=>window.clearInterval(t)},[cooldown]);const score=passwordStrength(newPassword);const request=async()=>{if(!email)return;setBusy(true);const {error}=await supabase.auth.signInWithOtp({email,options:{shouldCreateUser:false}});setBusy(false);if(error)toast.error(error.message);else{setSent(true);setCooldown(60);toast.success("OTP sent to your verified email.")}};const verify=async()=>{if(!/^\d{6}$/.test(otp))return toast.error("Enter the 6-digit OTP.");if(score<3)return toast.error("Choose a stronger password.");if(newPassword!==confirm)return toast.error("Passwords do not match.");setBusy(true);const {error:ve}=await supabase.auth.verifyOtp({email,token:otp,type:"email"});if(ve){setBusy(false);return toast.error(ve.message)}const {error}=await supabase.auth.updateUser({password:newPassword});setBusy(false);if(error)toast.error(error.message);else{setSent(false);setOtp("");setNewPassword("");setConfirm("");toast.success("Password changed successfully.")}};return <div className="space-y-5"><CardSection title="Request OTP" description={`A one-time code will be sent to ${email||"your verified email"}.`}><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold">Step 1 — verify your email</p><p className="text-sm text-muted-foreground">Use the real Supabase email OTP flow.</p></div><Button onClick={()=>void request()} disabled={busy||cooldown>0}>{cooldown?`Resend in ${cooldown}s`:sent?"Resend OTP":"Request OTP"}</Button></div></CardSection><CardSection title="Verify and change password" description="Step 2 — verify the OTP, then update the authenticated Supabase user."><div className="grid gap-4 sm:grid-cols-2"><Field label="OTP" value={otp} onChange={(v)=>setOtp(v.replace(/\D/g,"").slice(0,6))} placeholder="6-digit code" disabled={!sent}/><div/><Field label="New password" value={newPassword} onChange={setNewPassword} type="password" disabled={!sent}/><Field label="Confirm password" value={confirm} onChange={setConfirm} type="password" disabled={!sent}/></div><div className="mt-4 rounded-xl border border-border p-4"><div className="flex justify-between text-xs"><span className="font-semibold">Password strength</span><span>{["Very weak","Weak","Fair","Strong","Very strong"][score]}</span></div><div className="mt-2 h-1.5 rounded-full bg-secondary"><div className="h-full rounded-full bg-accent" style={{width:`${score*25}%`}}/></div></div><Button className="mt-5" onClick={()=>void verify()} disabled={!sent||busy}>{busy?"Verifying…":"Verify OTP & change password"}</Button></CardSection></div>}
function passwordStrength(value:string){let s=0;if(value.length>=8)s++;if(/[A-Z]/.test(value)&&/[a-z]/.test(value))s++;if(/\d/.test(value))s++;if(/[^A-Za-z0-9]/.test(value))s++;return s}

function Sessions(){const [sessions,setSessions]=useState<any[]>([]);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const load=useCallback(async()=>{setLoading(true);const {data,error}=await supabase.functions.invoke("account-security",{body:{action:"get"}});if(error)toast.error(error.message);setSessions(data?.sessions??[]);setLoading(false)},[]);useEffect(()=>{void load()},[load]);const revoke=async(id:string)=>{setBusy(true);const {data,error}=await supabase.functions.invoke("account-security",{body:{action:"revoke",sessionId:id}});setBusy(false);if(error)toast.error(error.message);else if(!data?.revoked)toast.error("Session could not be revoked.");else{toast.success("Session revoked.");await load()}};const revokeOthers=async()=>{setBusy(true);const {data,error}=await supabase.functions.invoke("account-security",{body:{action:"revoke_all_others"}});setBusy(false);if(error)toast.error(error.message);else{toast.success(`${data?.revoked??0} other session(s) signed out.`);await load()}};return <div className="space-y-5"><CardSection title="Active sessions" description="Only data returned by the existing account-security Edge Function is displayed."><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={()=>void load()}><CircleHelp className="mr-2 size-4"/>Refresh</Button><Button onClick={()=>void revokeOthers()} disabled={busy||sessions.filter((s)=>!s.current).length===0}>Sign out other devices</Button></div><div className="mt-5 grid gap-3">{loading?<Loading/>:sessions.length===0?<div className="rounded-xl border border-dashed border-border p-6 text-center text-sm text-muted-foreground">No session records were returned.</div>:sessions.map((session)=><div key={session.session_id} className="rounded-xl border border-border bg-surface p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{deviceName(session.user_agent)}</p>{session.current&&<span className="rounded-full bg-accent-soft px-2 py-1 text-[10px] font-bold uppercase text-accent-ink">Current session</span>}</div><p className="mt-1 text-xs text-muted-foreground">{session.ip?`IP ${session.ip}`:"IP not recorded"} · Last active {session.updated_at?new Date(session.updated_at).toLocaleString():"Unknown"}</p><p className="mt-1 max-w-2xl truncate text-xs text-muted-foreground">{session.user_agent??"User agent not recorded"}</p></div>{!session.current&&<Button variant="outline" disabled={busy} onClick={()=>void revoke(session.session_id)}>Sign out</Button>}</div><p className="mt-3 text-[11px] text-muted-foreground">Created {session.created_at?new Date(session.created_at).toLocaleString():"Unknown"}</p></div>)}</div></CardSection><Link to="/settings/sessions/revoke" className="inline-flex items-center gap-2 text-sm font-semibold text-accent-ink">Open sign-out confirmation <ArrowRight className="size-4"/></Link></div>}
function deviceName(ua:string|null){if(!ua)return"Unknown device";if(/iphone|ipad|android/i.test(ua))return"Mobile device";if(/macintosh|mac os/i.test(ua))return"Mac browser";if(/windows/i.test(ua))return"Windows browser";if(/linux/i.test(ua))return"Linux browser";return"Desktop browser"}

function Advanced(){const {store,advanced,loading,reload}=useSettingsData();const {role}=useStoreContext();const canManage=role==="owner"||role==="manager";const groups=[{key:"operations",title:"Store operations",rows:[["lowStockAlerts","Low stock alerts"],["outOfStockAlerts","Out-of-stock alerts"],["orderNotifications","Order notifications"],["customerNotifications","Customer notifications"]]},{key:"pos",title:"POS",rows:[["posSounds","POS sounds"],["barcodeAutofocus","Barcode autofocus"],["autoReceiptPrinting","Automatic receipt printing"]]},{key:"inventory",title:"Inventory",rows:[["negativeStockProtection","Negative-stock protection"],["inventoryValuation","Inventory valuation"],["branchAwareInventory","Branch-aware inventory"]]},{key:"security",title:"Security",rows:[["activityLogging","Activity logging"],["destructiveConfirmations","Destructive-action confirmations"],["sessionTimeout","Session timeout"],["staffPin","Staff PIN"]]},{key:"storefront",title:"Storefront",rows:[["searchSuggestions","Search suggestions"],["drafts","Drafts"],["seo","SEO"],["socialSharing","Social sharing"]]},{key:"developer",title:"Developer",rows:[["apiAccess","API access"],["webhooks","Webhooks"]]},{key:"experimental",title:"Experimental",rows:[["loyaltyPoints","Loyalty points"],["discountCodes","Discount codes"],["aiAutomation","AI automation"]]}];const [values,setValues]=useState<any>({});const [initial,setInitial]=useState<any>({});const [saving,setSaving]=useState(false);useEffect(()=>{setValues(advanced);setInitial(advanced)},[advanced]);if(loading)return <Loading/>;const dirty=JSON.stringify(values)!==JSON.stringify(initial);const update=(group:string,key:string,v:boolean)=>setValues((x:any)=>({...x,[group]:{...(x[group]??{}),[key]:v}}));const save=async()=>{if(!store?.id||!canManage)return;setSaving(true);try{const {error}=await db.from("store_advanced_settings").upsert({store_id:store.id,settings:values,updated_at:new Date().toISOString()},{onConflict:"store_id"});if(error)throw new Error(error.message);setInitial(values);await reload();toast.success("Advanced settings saved.")}catch(e){toast.error(e instanceof Error?e.message:"Could not save advanced settings.")}finally{setSaving(false)}};return <div className="space-y-5">{groups.map((group)=><CardSection key={group.key} title={group.title}>{group.rows.map(([key,label])=><ToggleRow key={key} label={label} description={`${label} is stored per store in the existing advanced settings record.`} checked={values[group.key]?.[key]!==false} onChange={(v)=>update(group.key,key,v)}/>)}</CardSection>)}<CardSection title="Developer controls" description="No fake API key or webhook manager is created here."><div className="grid gap-3"><div className="rounded-xl border border-border p-4"><p className="font-semibold">API access</p><p className="mt-1 text-sm text-muted-foreground">The existing Strap data model is preserved; this Settings rebuild does not invent an API-key management system.</p></div><div className="rounded-xl border border-border p-4"><p className="font-semibold">Webhooks</p><p className="mt-1 text-sm text-muted-foreground">No dedicated webhook manager is exposed until the production backend supports one.</p></div></div></CardSection>{!canManage&&<ReadOnly/>}<SaveBar dirty={dirty&&canManage} saving={saving} discard={()=>setValues(initial)} save={()=>void save()}/></div>}
